"""Recording via CS2's own offline demo player (no injection, no HLAE)."""
from __future__ import annotations
import subprocess
from dataclasses import dataclass
from pathlib import Path
from .detect import Highlight

CS2_APPID = "730"


def make_cfg(demo_name: str, h: Highlight, tickrate: int = 64, hide_hud: bool = False) -> str:
    """cfg exec'd from csgo/cfg. Only demo/spectator/cosmetic cvars."""
    lines = [
        "// generated by cs2-clips – offline demo playback only",
        f'playdemo "{demo_name}"',
        "demo_timescale 1",
        f"demo_gototick {h.start_tick}",
        f"spec_player {h.steamid}" if h.steamid.isdigit() and len(h.steamid) > 10 else f'spec_player "{h.name}"',
        "spec_mode 1",            # first-person
        "// demo UI stays closed (shift+F2 toggles it manually)",
        "cl_draw_only_deathnotices 1" if hide_hud else "cl_drawhud 1",
        "voice_enable 0",
    ]
    return "\n".join(lines) + "\n"


def cs2_launch_args(steam_exe: str, cfg_name: str, width: int = 1920, height: int = 1080) -> list[str]:
    # -insecure: VAC disabled for this session -> no online/VAC-protected play possible.
    # +exec runs our cfg, which immediately starts demo playback.
    return [steam_exe, "-applaunch", CS2_APPID, "-insecure", "-novid", "-console",
            "-fullscreen", "-w", str(width), "-h", str(height), "+exec", cfg_name]


def check_offline_safety(args: list[str]) -> None:
    """Refuse anything that is not an -insecure demo-playback launch."""
    if "-insecure" not in args:
        raise RuntimeError("Refusing: CS2 must be launched with -insecure (offline demo playback only).")
    banned = {"+connect", "+map", "+matchmaking", "-hlae", "+gameui_activate"}
    if banned & set(args):
        raise RuntimeError("Refusing: launch args would start online/non-demo play.")


def is_cs2_running() -> bool:
    try:
        out = subprocess.run(["tasklist", "/FI", "IMAGENAME eq cs2.exe"], capture_output=True, text=True).stdout
        return "cs2.exe" in out
    except FileNotFoundError:
        return False


def ffmpeg_gdigrab_cmd(out: Path, seconds: float, fps: int = 60, title: str | None = "Counter-Strike 2",
                       ffmpeg: str = "ffmpeg") -> list[str]:
    src = ["-i", f"title={title}"] if title else ["-i", "desktop"]
    return [ffmpeg, "-y", "-f", "gdigrab", "-framerate", str(fps), *src, "-t", f"{seconds:.2f}",
            "-c:v", "libx264", "-preset", "veryfast", "-crf", "18", "-pix_fmt", "yuv420p", str(out)]


def clip_seconds(h: Highlight, tickrate: int = 64) -> float:
    return max(1.0, (h.end_tick - h.start_tick) / tickrate)


@dataclass
class ObsRecorder:
    """obs-websocket v5 via obsws-python (optional dependency)."""
    host: str = "localhost"
    port: int = 4455
    password: str = ""

    def __post_init__(self):
        import obsws_python as obs
        self.cl = obs.ReqClient(host=self.host, port=self.port, password=self.password, timeout=5)

    def start(self):
        self.cl.start_record()

    def stop(self) -> str:
        return self.cl.stop_record().output_path
